fn inRanges(table: []const Range, cp: u32) bool {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = table[mid];
        if (cp < r.lo) {
            hi = mid;
        } else if (cp > r.hi) {
            lo = mid + 1;
        } else return true;
    }
    return false;
}

pub fn isStart(cp: u32) bool {
    return inRanges(&start, cp);
}

pub fn isCont(cp: u32) bool {
    return inRanges(&cont, cp);
}
